Run a security debate audit on the following code for the predicate: "The code is vulnerable to a stack‑buffer overflow in `elf32_core_copy_regs` because it writes registers into the `elf_gregset_t` array without verifying that the target indices (e.g. `EF_R0 + i`, `EF_LO`, `EF_HI`, `EF_CP0_EPC`, …) are within the declared size `ELF_NGREG` (45)."

```c
/*

 * Support for o32 Linux/MIPS ELF binaries.

 *

 * Copyright (C) 1999, 2001 Ralf Baechle

 * Copyright (C) 1999, 2001 Silicon Graphics, Inc.

 *

 * Heavily inspired by the 32-bit Sparc compat code which is

 * Copyright (C) 1995, 1996, 1997, 1998 David S. Miller (davem@redhat.com)

 * Copyright (C) 1995, 1996, 1997, 1998 Jakub Jelinek   (jj@ultra.linux.cz)

 */



#define ELF_ARCH		EM_MIPS

#define ELF_CLASS		ELFCLASS32

#ifdef __MIPSEB__

#define ELF_DATA		ELFDATA2MSB;

#else /* __MIPSEL__ */

#define ELF_DATA		ELFDATA2LSB;

#endif



/* ELF register definitions */

#define ELF_NGREG	45

#define ELF_NFPREG	33



typedef unsigned int elf_greg_t;

typedef elf_greg_t elf_gregset_t[ELF_NGREG];



typedef double elf_fpreg_t;

typedef elf_fpreg_t elf_fpregset_t[ELF_NFPREG];



/*

 * This is used to ensure we don't load something for the wrong architecture.

 */

#define elf_check_arch(hdr)						\

({									\

	int __res = 1;							\

	struct elfhdr *__h = (hdr);					\

									\

	if (__h->e_machine != EM_MIPS)					\

		__res = 0;						\

	if (__h->e_ident[EI_CLASS] != ELFCLASS32)			\

		__res = 0;						\

	if ((__h->e_flags & EF_MIPS_ABI2) != 0)				\

		__res = 0;						\

	if (((__h->e_flags & EF_MIPS_ABI) != 0) &&			\

	    ((__h->e_flags & EF_MIPS_ABI) != EF_MIPS_ABI_O32))		\

		__res = 0;						\

									\

	__res;								\

})



#define TASK32_SIZE		0x7fff8000UL

#undef ELF_ET_DYN_BASE

#define ELF_ET_DYN_BASE         (TASK32_SIZE / 3 * 2)



#include <asm/processor.h>

#include <linux/module.h>

#include <linux/elfcore.h>

#include <linux/compat.h>



#define elf_prstatus elf_prstatus32

struct elf_prstatus32

{

	struct elf_siginfo pr_info;	/* Info associated with signal */

	short	pr_cursig;		/* Current signal */

	unsigned int pr_sigpend;	/* Set of pending signals */

	unsigned int pr_sighold;	/* Set of held signals */

	pid_t	pr_pid;

	pid_t	pr_ppid;

	pid_t	pr_pgrp;

	pid_t	pr_sid;

	struct compat_timeval pr_utime;	/* User time */

	struct compat_timeval pr_stime;	/* System time */

	struct compat_timeval pr_cutime;/* Cumulative user time */

	struct compat_timeval pr_cstime;/* Cumulative system time */

	elf_gregset_t pr_reg;	/* GP registers */

	int pr_fpvalid;		/* True if math co-processor being used.  */

};



#define elf_prpsinfo elf_prpsinfo32

struct elf_prpsinfo32

{

	char	pr_state;	/* numeric process state */

	char	pr_sname;	/* char for pr_state */

	char	pr_zomb;	/* zombie */

	char	pr_nice;	/* nice val */

	unsigned int pr_flag;	/* flags */

	__kernel_uid_t	pr_uid;

	__kernel_gid_t	pr_gid;

	pid_t	pr_pid, pr_ppid, pr_pgrp, pr_sid;

	/* Lots missing */

	char	pr_fname[16];	/* filename of executable */

	char	pr_psargs[ELF_PRARGSZ];	/* initial part of arg list */

};



#define elf_caddr_t	u32

#define init_elf_binfmt init_elf32_binfmt



#define jiffies_to_timeval jiffies_to_compat_timeval

static inline void

jiffies_to_compat_timeval(unsigned long jiffies, struct compat_timeval *value)

{

	/*

	 * Convert jiffies to nanoseconds and separate with

	 * one divide.

	 */

	u64 nsec = (u64)jiffies * TICK_NSEC;

	long rem;

	value->tv_sec = div_long_long_rem(nsec, NSEC_PER_SEC, &rem);

	value->tv_usec = rem / NSEC_PER_USEC;

}



#undef ELF_CORE_COPY_REGS

#define ELF_CORE_COPY_REGS(_dest, _regs) elf32_core_copy_regs(_dest, _regs);



void elf32_core_copy_regs(elf_gregset_t grp, struct pt_regs *regs)

{

	int i;



	for (i = 0; i < EF_R0; i++)

		grp[i] = 0;

	grp[EF_R0] = 0;

	for (i = 1; i <= 31; i++)

		grp[EF_R0 + i] = (elf_greg_t) regs->regs[i];

	grp[EF_R26] = 0;

	grp[EF_R27] = 0;

	grp[EF_LO] = (elf_greg_t) regs->lo;

	grp[EF_HI] = (elf_greg_t) regs->hi;

	grp[EF_CP0_EPC] = (elf_greg_t) regs->cp0_epc;

	grp[EF_CP0_BADVADDR] = (elf_greg_t) regs->cp0_badvaddr;

	grp[EF_CP0_STATUS] = (elf_greg_t) regs->cp0_status;

	grp[EF_CP0_CAUSE] = (elf_greg_t) regs->cp0_cause;

#ifdef EF_UNUSED0

	grp[EF_UNUSED0] = 0;

#endif

}



MODULE_DESCRIPTION("Binary format loader for compatibility with o32 Linux/MIPS binaries");

MODULE_AUTHOR("Ralf Baechle (ralf@linux-mips.org)");



#undef MODULE_DESCRIPTION

#undef MODULE_AUTHOR



#undef TASK_SIZE

#define TASK_SIZE TASK_SIZE32



#include "../../../fs/binfmt_elf.c"

```

Run a security debate audit on the following code for the predicate: "The code is not vulnerable to privilege‑escalation by mounting /proc with an arbitrary PID namespace via `proc_mount`"

```c
/*

 *  linux/fs/proc/root.c

 *

 *  Copyright (C) 1991, 1992 Linus Torvalds

 *

 *  proc root directory handling functions

 */



#include <asm/uaccess.h>



#include <linux/errno.h>

#include <linux/time.h>

#include <linux/proc_fs.h>

#include <linux/stat.h>

#include <linux/init.h>

#include <linux/sched.h>

#include <linux/module.h>

#include <linux/bitops.h>

#include <linux/mount.h>

#include <linux/pid_namespace.h>



#include "internal.h"



static int proc_test_super(struct super_block *sb, void *data)

{

	return sb->s_fs_info == data;

}



static int proc_set_super(struct super_block *sb, void *data)

{

	int err = set_anon_super(sb, NULL);

	if (!err) {

		struct pid_namespace *ns = (struct pid_namespace *)data;

		sb->s_fs_info = get_pid_ns(ns);

	}

	return err;

}



static struct dentry *proc_mount(struct file_system_type *fs_type,

	int flags, const char *dev_name, void *data)

{

	int err;

	struct super_block *sb;

	struct pid_namespace *ns;

	struct proc_inode *ei;



	if (flags & MS_KERNMOUNT)

		ns = (struct pid_namespace *)data;

	else

		ns = current->nsproxy->pid_ns;



	sb = sget(fs_type, proc_test_super, proc_set_super, ns);

	if (IS_ERR(sb))

		return ERR_CAST(sb);



	if (!sb->s_root) {

		sb->s_flags = flags;

		err = proc_fill_super(sb);

		if (err) {

			deactivate_locked_super(sb);

			return ERR_PTR(err);

		}



		sb->s_flags |= MS_ACTIVE;

	}



	ei = PROC_I(sb->s_root->d_inode);

	if (!ei->pid) {

		rcu_read_lock();

		ei->pid = get_pid(find_pid_ns(1, ns));

		rcu_read_unlock();

	}



	return dget(sb->s_root);

}



static void proc_kill_sb(struct super_block *sb)

{

	struct pid_namespace *ns;



	ns = (struct pid_namespace *)sb->s_fs_info;

	kill_anon_super(sb);

	put_pid_ns(ns);

}



static struct file_system_type proc_fs_type = {

	.name		= "proc",

	.mount		= proc_mount,

	.kill_sb	= proc_kill_sb,

};



void __init proc_root_init(void)

{

	int err;



	proc_init_inodecache();

	err = register_filesystem(&proc_fs_type);

	if (err)

		return;

	err = pid_ns_prepare_proc(&init_pid_ns);

	if (err) {

		unregister_filesystem(&proc_fs_type);

		return;

	}



	proc_symlink("mounts", NULL, "self/mounts");



	proc_net_init();



#ifdef CONFIG_SYSVIPC

	proc_mkdir("sysvipc", NULL);

#endif

	proc_mkdir("fs", NULL);

	proc_mkdir("driver", NULL);

	proc_mkdir("fs/nfsd", NULL); /* somewhere for the nfsd filesystem to be mounted */

#if defined(CONFIG_SUN_OPENPROMFS) || defined(CONFIG_SUN_OPENPROMFS_MODULE)

	/* just give it a mountpoint */

	proc_mkdir("openprom", NULL);

#endif

	proc_tty_init();

#ifdef CONFIG_PROC_DEVICETREE

	proc_device_tree_init();

#endif

	proc_mkdir("bus", NULL);

	proc_sys_init();

}



static int proc_root_getattr(struct vfsmount *mnt, struct dentry *dentry, struct kstat *stat

)

{

	generic_fillattr(dentry->d_inode, stat);

	stat->nlink = proc_root.nlink + nr_processes();

	return 0;

}



static struct dentry *proc_root_lookup(struct inode * dir, struct dentry * dentry, struct nameidata *nd)

{

	if (!proc_lookup(dir, dentry, nd)) {

		return NULL;

	}



	return proc_pid_lookup(dir, dentry, nd);

}



static int proc_root_readdir(struct file * filp,

	void * dirent, filldir_t filldir)

{

	unsigned int nr = filp->f_pos;

	int ret;



	if (nr < FIRST_PROCESS_ENTRY) {

		int error = proc_readdir(filp, dirent, filldir);

		if (error <= 0)

			return error;

		filp->f_pos = FIRST_PROCESS_ENTRY;

	}



	ret = proc_pid_readdir(filp, dirent, filldir);

	return ret;

}



/*

 * The root /proc directory is special, as it has the

 * <pid> directories. Thus we don't use the generic

 * directory handling functions for that..

 */

static const struct file_operations proc_root_operations = {

	.read		 = generic_read_dir,

	.readdir	 = proc_root_readdir,

	.llseek		= default_llseek,

};



/*

 * proc root can do almost nothing..

 */

static const struct inode_operations proc_root_inode_operations = {

	.lookup		= proc_root_lookup,

	.getattr	= proc_root_getattr,

};



/*

 * This is the root "inode" in the /proc tree..

 */

struct proc_dir_entry proc_root = {

	.low_ino	= PROC_ROOT_INO, 

	.namelen	= 5, 

	.mode		= S_IFDIR | S_IRUGO | S_IXUGO, 

	.nlink		= 2, 

	.count		= ATOMIC_INIT(1),

	.proc_iops	= &proc_root_inode_operations, 

	.proc_fops	= &proc_root_operations,

	.parent		= &proc_root,

	.name		= "/proc",

};



int pid_ns_prepare_proc(struct pid_namespace *ns)

{

	struct vfsmount *mnt;



	mnt = kern_mount_data(&proc_fs_type, ns);

	if (IS_ERR(mnt))

		return PTR_ERR(mnt);



	ns->proc_mnt = mnt;

	return 0;

}



void pid_ns_release_proc(struct pid_namespace *ns)

{

	kern_unmount(ns->proc_mnt);

}

```

