	struct super_block *sb;

	struct pid_namespace *ns;

	char *options;



	if (flags & MS_KERNMOUNT) {

		ns = (struct pid_namespace *)data;

		options = NULL;

	} else {

		ns = task_active_pid_ns(current);

		options = data;



