	.namelen	= 5, 

	.mode		= S_IFDIR | S_IRUGO | S_IXUGO, 

	.nlink		= 2, 

	.count		= ATOMIC_INIT(1),

	.proc_iops	= &proc_root_inode_operations, 

	.proc_fops	= &proc_root_operations,

