		ioc->ioprio = ioprio;

		put_io_context(ioc);

	}



	return err;

}

EXPORT_SYMBOL_GPL(set_task_ioprio);



SYSCALL_DEFINE3(ioprio_set, int, which, int, who, int, ioprio)

