				ret = set_task_ioprio(p, ioprio);

				if (ret)

					break;

			} while_each_pid_thread(pgrp, PIDTYPE_PGID, p);

			break;

		case IOPRIO_WHO_USER:

			uid = make_kuid(current_user_ns(), who);

			if (!uid_valid(uid))

				break;

			if (!who)

				user = current_user();

			else

				user = find_user(uid);



			if (!user)

				break;



			do_each_thread(g, p) {

				if (!uid_eq(task_uid(p), uid) ||

				    !task_pid_vnr(p))

					continue;

				ret = set_task_ioprio(p, ioprio);

				if (ret)

					goto free_uid;

			} while_each_thread(g, p);

