int pid_ns_prepare_proc(struct pid_namespace *ns)

{

	struct vfsmount *mnt;



	mnt = kern_mount_data(&proc_fs_type, ns);

	if (IS_ERR(mnt))

		return PTR_ERR(mnt);



	ns->proc_mnt = mnt;

	return 0;

}



void pid_ns_release_proc(struct pid_namespace *ns)

{

	kern_unmount(ns->proc_mnt);

}

